venmo_balance_before = apis.venmo.show_venmo_balance(access_token=venmo_token).get('venmo_balance')
print('balance_before', venmo_balance_before)

cards = apis.venmo.show_payment_cards(access_token=venmo_token)
# filter non-expired? we only know expiry_month/year; but API didn't give current date. We'll just try cards sequentially.
active_cards = [c for c in cards if c.get('payment_card_id') is not None]
print('active_cards', [(c.get('payment_card_id'), c.get('card_name'), c.get('expiry_year'), c.get('expiry_month')) for c in active_cards])

amount_attempts = [200,150,120,100,80,60,50,40,30,20,10]

def try_add(card_id, amt_list):
    for amt in amt_list:
        try:
            res = apis.venmo.add_to_venmo_balance(amount=amt, payment_card_id=card_id, access_token=venmo_token)
            return {'success': True, 'amount_added': amt, 'res': res}
        except Exception as e:
            print('add_failed_card', card_id, 'amt', amt, 'err', str(e))
    return {'success': False}

# Try to add up toward 234 using any cards
remaining_target = 234
current_balance = venmo_balance_before
add_records = []

for c in active_cards:
    card_id = c.get('payment_card_id')
    if current_balance >= remaining_target:
        break
    # Determine max we try from this point: try amounts down from min(remaining, 200) maybe
    amt_list = [a for a in amount_attempts if a <= (remaining_target - current_balance)]
    if not amt_list:
        # if remaining is less than smallest attempt, try exact remaining if >0
        if remaining_target - current_balance > 0:
            amt_list = [remaining_target - current_balance]
        else:
            amt_list = []
    print('trying_card', card_id, 'amt_list', amt_list)
    out = try_add(card_id, amt_list)
    if out.get('success'):
        add_records.append({'card_id': card_id, 'amount_added': out['amount_added'], 'bank_transfer_id': out['res'].get('bank_transfer_id')})
        current_balance = apis.venmo.show_venmo_balance(access_token=venmo_token).get('venmo_balance')
        print('balance_after_card', card_id, current_balance)
    else:
        print('card_exhausted_or_no_success', card_id)

print('add_records', add_records)
print('balance_final_before_send', apis.venmo.show_venmo_balance(access_token=venmo_token).get('venmo_balance'))

